#include "EventBus.hpp"
#include <string.h>

void EventBus::subscribe(const char* topic, EventCallback callback, void* ctx) {
    if (topic == nullptr || callback == nullptr) return;
    if (subscriptionCount >= 32) return; // Table capacity boundary reached

    // Safe string copy with truncation guard
    Subscription& sub = subscriptions[subscriptionCount];
    strncpy(sub.topic, topic, sizeof(sub.topic) - 1);
    sub.topic[sizeof(sub.topic) - 1] = '\0';

    sub.callback = callback;
    sub.ctx = ctx;

    subscriptionCount++;
}

void EventBus::unsubscribe(const char* topic, EventCallback callback, void* ctx) {
    if (topic == nullptr || callback == nullptr) return;

    size_t i = 0;
    while (i < subscriptionCount) {
        Subscription& sub = subscriptions[i];

        // Match entry criteria
        if (strcmp(sub.topic, topic) == 0 && sub.callback == callback && sub.ctx == ctx) {
            // Shift subsequent elements left to maintain contiguity
            for (size_t j = i; j < subscriptionCount - 1; j++) {
                subscriptions[j] = subscriptions[j + 1];
            }
            subscriptionCount--;
            // Do not increment i, evaluate shifted element in next iteration
        } else {
            i++;
        }
    }
}

