 * - labelWidget::render: renders label.
 */

#include "labelWidget.hpp"
#include <string.h>

labelWidget::labelWidget(int16_t x, int16_t y, int16_t w, int16_t h, const char* text, TextAlign align, const uint8_t* fontPtr)
    : iGfxWidget(x, y, w, h), alignment(align), font(fontPtr) {
    currentText[0] = '\0';
    if (text) {
        setText(text);
    }
}

void labelWidget::setText(const char* newText) {
    if (newText == nullptr) {
        currentText[0] = '\0';
        return;
    }
    // Safely copy text
    size_t i = 0;
    while (i < sizeof(currentText) - 1 && newText[i] != '\0') {
        currentText[i] = newText[i];
        i++;
    }
    currentText[i] = '\0';
}

void labelWidget::render(U8G2& display) {
    if (!isVisible || currentText[0] == '\0') {
        return;
    }
    drawText(display, currentText, x, y, width, height, alignment, false, font);
}
