scrollingTextWidget::scrollingTextWidget(int16_t x, int16_t y, int16_t w, int16_t h, const uint8_t* fontPtr)
    : iGfxWidget(x, y, w, h), scrollX(0), messageWidth(0), lastScrollMs(0),
      needsScroll(false), needsLayout(true), font(fontPtr), scrollFinished(false), screenWidth(128) {
    currentText[0] = '\0';
}

void scrollingTextWidget::setText(const char* newText) {
    if (newText == nullptr) {
        currentText[0] = '\0';
        needsLayout = true;
        return;
    }
    if (strcmp(currentText, newText) == 0) {
        return;
    }
    strncpy(currentText, newText, sizeof(currentText) - 1);
    currentText[sizeof(currentText) - 1] = '\0';
    needsLayout = true;
    scrollFinished = false;
}

