#include <unity.h>
#include <EventBus.hpp>
#include <cstring>

// --- Helper context structure ---
struct TestEventCtx {
    int callCount;
    char lastTopic[64];
    int lastPayloadVal;
};

// --- Static Callback Function ---
static void testCallback(const char* topic, const void* payload, void* ctx) {
    auto* c = static_cast<TestEventCtx*>(ctx);
    c->callCount++;
    strncpy(c->lastTopic, topic, sizeof(c->lastTopic) - 1);
    c->lastTopic[sizeof(c->lastTopic) - 1] = '\0';
    if (payload) {
        c->lastPayloadVal = *static_cast<const int*>(payload);
    }
}

void test_event_bus_publish_subscribe() {
    EventBus bus;
    TestEventCtx ctx = {0, "", 0};

    // Subscribe
    bus.subscribe("test.topic", testCallback, &ctx);

    // Publish
    int val = 42;
    bus.publish("test.topic", &val);

    TEST_ASSERT_EQUAL(1, ctx.callCount);
    TEST_ASSERT_EQUAL_STRING("test.topic", ctx.lastTopic);
    TEST_ASSERT_EQUAL(42, ctx.lastPayloadVal);
}

void test_event_bus_unsubscribe() {
    EventBus bus;
    TestEventCtx ctx = {0, "", 0};

    bus.subscribe("test.topic", testCallback, &ctx);

    int val = 100;
    bus.publish("test.topic", &val);
    TEST_ASSERT_EQUAL(1, ctx.callCount);

    // Unsubscribe
    bus.unsubscribe("test.topic", testCallback, &ctx);

    bus.publish("test.topic", &val);
    TEST_ASSERT_EQUAL(1, ctx.callCount); // Call count should not increment
}

