"void test_display_carousel_board_rotation() {
    TimeManager timeMgr;
    U8G2DisplayModule disp(&timeMgr);
    disp.begin();
    disp.setSleepTimeout(3000); // Prevent sleep during rotation test

    // Set short carousel rotation interval (e.g. 5 seconds)
    FrameworkConfig config;
    config.carouselIntervalSecs = 5;
    disp.reapplyConfig(config);

    MockDisplayBoard board1("Board1");
    MockDisplayBoard board2("Board2");

    disp.registerBoard(&board1);
    disp.registerBoard(&board2);

    mockSystemMillis = 0;
    disp.clearOverride();

    // T = 0
    disp.tick(0);
    TEST_ASSERT_EQUAL(1, board1.activateCount);
    TEST_ASSERT_EQUAL(0, board2.activateCount);

    // T = 4000 (4s - no switch yet)
    mockSystemMillis = 4000;
    disp.tick(4000);
    TEST_ASSERT_EQUAL(1, board1.activateCount);
    TEST_ASSERT_EQUAL(0, board2.activateCount);

    // T = 5100 (5.1s - exceeds 5s, should switch)
    mockSystemMillis = 5100;
    disp.tick(5100);
    TEST_ASSERT_EQUAL(1, board1.deactivateCount);
    TEST_ASSERT_EQUAL(1, board2.activateCount);

    // T = 10200 (10.2s - exceeds another 5s, should switch back to Board1)
    mockSystemMillis = 10200;
    disp.tick(10200);
    TEST_ASSERT_EQUAL(1, board2.deactivateCount);
    TEST_ASSERT_EQUAL(2, board1.activateCount);
}"

