#include <Arduino.h>
#include <AppFoundation.h>
#include <Application.hpp>
#include <u8g2DisplayModule.hpp>
#include "myApp.hpp"

// Framework instances
static Application app;
static U8G2DisplayModule displayModule(&app.getTimeManager());

// User application instance
static MyApp myApp(&app, &displayModule);

void setup() {
    Serial.begin(115200);
    while (!Serial) {
        delay(10); // Wait for native USB serial port (e.g. S3 Nano)
    }

    Serial.println("[System] Initializing ESP32 App Foundation...");

    // 1. Register framework modules to composition root
    app.registerTickable(&displayModule);
    app.registerConfigConsumer(&displayModule);
    app.setStatusReporter(&displayModule);

    // 2. Setup user application (this binds myApp's custom hooks and display boards)
    myApp.setup();

    // 3. Configure and start kernel lifecycle
    FrameworkConfig config;
    strncpy(config.hostname, "my-esp32-app", sizeof(config.hostname) - 1);
    config.carouselIntervalSecs = 10;

    // Boot the system
    app.begin(config);

    Serial.println("[System] Kernel boot phase completed successfully.");
}

void loop() {
    // Dispatch periodic task scheduler and loop ticks
    app.tick();
}
